  insert into public.brands (name, website, description, country, status) values ('Sigma Beauty', 'https://www.sigmabeauty.com', 'US indie beauty brand founded in 2009, known for patented makeup brushes, brush-care tools and color cosmetics; directories list its affiliate program at 10% per sale, with the network reported as ShareASale by one directory and Impact by others.', 'United States', 'published') returning id into bid;
