  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'ShareASale / Impact (reported)', 10, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://linkclicky.com/affiliate-program/sigma/.', 'https://www.sigmabeauty.com/influencer-program', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Sigma Beauty Affiliate Program (ShareASale / Impact, reported)', 'https://www.sigmabeauty.com/influencer-program', null, 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkclicky.com/affiliate-program/sigma/', 'affiliate_directory', 'affiliate_program', 'LinkClicky (profile updated March 11, 2024) lists Sigma Beauty (website sigmabeauty.com) on ShareASale at 10% per sale with a 90-day cookie; affiliateprograms.com independently lists the Sigma program at 10% commissions on all sales with a VIP tier above it.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://brandid.app/programs/sigma-beauty', 'affiliate_directory', 'commission_rate', 'Directories agree on a 10% base rate but conflict on the network and cookie: Brandid lists the program on Impact at 10% (up to 15% VIP), a 2018 program write-up also names Impact Radius with a 30-day cookie, Lasso lists 10-15% with a 2-day cookie, and Shopper''s 4% figure is an outlier. The 10% base rate is recorded; the network is recorded as reported on both ShareASale and Impact. A creator platform (NewCollab) describes Sigma''s direct creator route as gifting-led PR, so the commission route is the network affiliate program recorded here. No earnings-cap statement was found, so the cap is unknown; no creator count is published, so saturation is also unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 15, 13, 9, 8, 4, '{"compensation": "A 10% base rate is agreed by several directories, with a reported VIP tier up to 15%; cookie terms conflict across sources.", "contact_access": "The brand runs its own influencer program page as the application route; no public partnerships email was found.", "credibility": "Established US brand founded in 2009; program evidence is directory-based and the network attribution conflicts between ShareASale and Impact.", "niche_fit": "Makeup brushes and cosmetics are a core UGC beauty category for tutorials, reviews and tool comparisons.", "opportunity_availability": "Open network program with the brand''s own influencer page as the entry point.", "ugc_evidence": "The brand maintains an influencer program page and a large creator following (#SigmaFam), though its direct creator route is described by one platform as gifting-led."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('ODEON', 'https://www.odeonworld.com', 'Indian beauty brand selling skincare, beauty and lifestyle products (35+ products across 9 categories, prices in rupees) whose own affiliate page runs a four-tier creator program through BixGrow, from a 15% base commission for nano creators up to 20% for professionals.', 'India', 'published') returning id into bid;
