  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'BixGrow (own portal)', 15, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://www.odeonworld.com/pages/become-an-affiliate.', 'https://www.odeonworld.com/pages/become-an-affiliate', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'ODEON Affiliate Program (BixGrow own portal)', 'https://www.odeonworld.com/pages/become-an-affiliate', null, 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.odeonworld.com/pages/become-an-affiliate', 'brand_site', 'affiliate_program', 'The brand''s own affiliate page (fetched) publishes creator tiers run through a BixGrow portal: Seedling nano creators (1K-10K followers) earn 15% base commission, Blossom micro influencers 18%, a Glow customer-referral tier 12%, and an Elite professional tier 20%, with automatic tier upgrades at published referred-sales thresholds, seasonal commission boosts and up to 22% on hero products. The recorded rate is the 15% base creator tier.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.odeonworld.com/pages/become-an-affiliate', 'brand_site', 'commission_cap', 'No earnings-cap or ''unlimited earnings'' statement appears on the fetched program page, so the cap is recorded as unknown. No creator count is published, so saturation is also unknown. The Elite tier targets professional MUAs and salon owners, but the program''s Seedling and Blossom tiers are creator tiers open from 1,000 followers, which is the route recorded here.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 17, 15, 8, 8, 3, '{"compensation": "15% base for nano creators with published tiers to 18% and 20% is a strong published structure for a smaller brand.", "contact_access": "Applications run through the brand''s own affiliate page and BixGrow portal; no public partnerships email is published.", "credibility": "Full tier terms are published on the brand''s own page, but the brand is India-focused with limited independent coverage in the sources checked.", "niche_fit": "Skincare and beauty products across 9 categories fit UGC routines and reviews, with tiers explicitly built for nano and micro creators.", "opportunity_availability": "Open signup from 1,000 followers at the Seedling tier.", "ugc_evidence": "A purpose-built tiered creator program with onboarding kits, affiliate managers at higher tiers and seasonal boosts is strong creator evidence."}'::jsonb);
