  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/62235', 'brand_site', 'affiliate_program', 'Skin Choice''s own Awin merchant profile (fetched) states the program runs in partnership with the Awin network and pays a competitive 10% commission on every confirmed sale, with a target geography of the United Kingdom and worldwide, full affiliate support and marketing materials, and the contact email marketing@skinchoice.com for inquiries and partnership opportunities.', 'verified', now());
