  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 12, 13, 13, 9, 3, '{"compensation": "A flat 10% on every confirmed sale, published on the brand''s own network profile, is a solid mid-tier rate.", "contact_access": "A named marketing contact email for partnership inquiries is published on the brand''s Awin profile.", "credibility": "Program terms are verified on the network profile the brand itself maintains; the brand is small with limited independent coverage.", "niche_fit": "Acne care and pimple patches are a proven, demonstrable UGC skincare niche with strong before/after content.", "opportunity_availability": "Open Awin program targeting the UK and worldwide.", "ugc_evidence": "The brand recruits affiliates directly on its network profile with marketing tools and ongoing guidance, though it publishes no separate creator program."}'::jsonb);
