  insert into public.brands (name, website, description, country, status) values ('SKN TO SKN', 'https://skntoskn.com', 'UK pregnancy-safe skincare brand developed with dermatologists and GPs for pregnancy, breastfeeding and hormonal skin, stocked in Boots and award-winning in the maternity category; its affiliate program runs on Webgains with a dedicated content-and-influencer commission tier.', 'United Kingdom', 'published') returning id into bid;
