  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'SKN TO SKN Affiliate Program (Webgains)', 'http://affi.io/m/skn-to-skn', null, 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'http://affi.io/m/skn-to-skn', 'affiliate_directory', 'affiliate_program', 'The brand''s Webgains program terms, reproduced on its affi.io program page (fetched), publish a baseline commission of 10% for new customers and 7% for existing customers, a Content & Influencers tier at 12% new / 10% existing, voucher-site rates of 5% / 3%, a 30-day cookie and a closed PPC policy. The recorded rate is the 10% baseline new-customer rate. The page''s summary header shows a conflicting ''3% to 3%'' revenue figure, which matches only the lowest voucher-site existing-customer rate; the detailed commission overview in the program terms is the basis for the recorded rate.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'http://affi.io/m/skn-to-skn', 'affiliate_directory', 'commission_cap', 'No earnings-cap or ''unlimited earnings'' statement appears in the fetched program terms, so the cap is recorded as unknown. The program page states the Webgains program launched about three months ago, but a launch date alone is not creator-count evidence, so saturation is also recorded as unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 22, 13, 13, 8, 9, 4, '{"compensation": "10% baseline on new customers, rising to 12% for content creators and influencers, is a solid published structure; existing-customer rates are lower at 7% / 10%.", "contact_access": "Affiliate contact runs through Webgains per the program terms; no public partnerships email is published.", "credibility": "Stocked in Boots nationwide with maternity-category awards per the program page; the brand is young and niche.", "niche_fit": "Pregnancy-safe skincare is narrower than general skincare, but it is a specific, underserved niche with a motivated audience and clinical credibility.", "opportunity_availability": "Open Webgains program, launched about three months before this research, with a published content-and-influencer tier.", "ugc_evidence": "A dedicated Content & Influencers commission tier in the program terms is direct evidence the brand recruits creators."}'::jsonb);
