  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Nuria Beauty Affiliate Program (Awin)', 'https://ui.awin.com/merchant-profile/90735', null, 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/90735', 'brand_site', 'affiliate_program', 'Nuria Beauty''s own Awin merchant profile (fetched) states the program offers a minimum 5% commission with an average order value of about $45, and describes the range as clean, vegan, non-GMO, gluten-free, Leaping Bunny-certified and carbon neutral, with a portion of all sales contributed to girls'' education. The recorded rate is the published 5% minimum.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://parade.com/942570/brittany-galla/here-are-the-seven-words-that-naomi-furgiule-founder-of-nuria-beauty-says-to-herself-before-a-big-meeting/', 'brand_site', 'brand_overview', 'Parade''s founder profile states Pennsylvania-based entrepreneur Naomi Furgiuele launched Nuria in November 2018 after leading face and sun R&D teams at Johnson & Johnson, and that the brand partners with She''s The First to fund girls'' education.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/90735', 'brand_site', 'commission_cap', 'No earnings-cap or ''unlimited earnings'' statement appears on the fetched Awin profile, so the cap is recorded as unknown. No creator count is published, so saturation is also unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 11, 9, 8, 9, 4, '{"compensation": "A published 5% minimum is a low floor, though the ''minimum'' wording implies higher rates are possible and the $45 average order value is disclosed.", "contact_access": "Contact runs through the brand''s website message link on its Awin profile; no public partnerships email is published.", "credibility": "Founded in 2018 by a former Johnson & Johnson R&D vice president, with Leaping Bunny certification and a documented education-giving program.", "niche_fit": "Clean, vegan, globally inspired skincare with a give-back story fits values-led UGC well.", "opportunity_availability": "Open Awin program with published terms on the brand''s own merchant profile.", "ugc_evidence": "An open network program exists, but the brand publishes no dedicated creator program page in the sources checked."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Yesim', 'https://yesim.app/', 'Global eSIM data provider selling prepaid mobile data plans for travellers across 200+ destinations. Its own affiliate page pays a 10% base commission with lifetime attribution across a customer''s first, second and recurring purchases, instant payouts once the balance reaches €100, and an explicit pitch to bloggers, creators and influencers; the page says 1,000+ creators already promote it, so saturation is not low, and its ''earn as much as your audience allows'' line is not an earnings-cap statement, so the cap stays unknown.', null, 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'travel'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Brand direct', 10, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://yesim.app/affiliate-program/.', 'https://yesim.app/affiliate-program/', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Yesim Affiliate Program (Brand direct)', 'https://yesim.app/affiliate-program/', 'https://yesim.app/affiliate-program/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://yesim.app/affiliate-program/', 'official_program_page', 'commission_rate', 'Yesim''s own affiliate page states a 10% base commission with lifetime commissions earned on first, second and recurring purchases, and instant payouts from a €100 balance. No earnings-cap statement appears on the page - ''earn as much as your audience allows'' is vague wording, not a cap statement - so commission_cap is recorded as unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://yesim.app/affiliate-program/', 'official_program_page', 'creator_program', 'The same page explicitly recruits bloggers, creators and influencers and says ''Join 1000+ bloggers, creators'' already promoting Yesim - a four-figure creator count is not low in absolute terms, so creator_saturation stays unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 16, 14, 9, 9, 4, '{"compensation": "10% base with lifetime commissions on recurring purchases and instant payouts from \u20ac100 is strong for a digital travel product; brand-published.", "contact_access": "Apply on the brand''s own page; no public affiliate email was verified.", "credibility": "Established global eSIM provider; rate and terms verified on its own page.", "niche_fit": "eSIM setup is now standard travel content - arrival-day connectivity, airport and packing-checklist videos all convert on it.", "opportunity_availability": "Open application on the brand page.", "ugc_evidence": "The brand''s own page is built for bloggers, creators and influencers, with lifetime attribution across repeat purchases."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Travala', 'https://www.travala.com/', 'Online travel agency booking hotels, flights, activities and car rentals worldwide, known for crypto-friendly payments. Its own affiliate page routes sign-up through Impact and publishes category rates - 5% on hotels, activities and car rentals, 4% on flights, plus a 0.5% bonus on new-user bookings; the 5% headline category rate is recorded.', null, 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'travel'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Impact', 5, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://www.travala.com/affiliate-program.', 'https://www.travala.com/affiliate-program', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Travala Affiliate Program (Impact)', 'https://www.travala.com/affiliate-program', 'https://www.travala.com/affiliate-program', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.travala.com/affiliate-program', 'official_program_page', 'commission_rate', 'Travala''s own affiliate page publishes the rate card - hotels, activities and car rentals at 5%, flights at 4%, plus a 0.5% new-user bonus - and links registration into Impact (app.impact.com). The 5% headline category rate is recorded with the flight rate documented here. No earnings-cap statement appears, so the cap is recorded as unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.travala.com/affiliate-program', 'official_program_page', 'creator_program', 'The same page presents an open affiliate program for travel publishers and creators with registration handled inside Impact. No creator counts are published, so creator_saturation stays unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 13, 11, 9, 8, 4, '{"compensation": "5% on hotels/activities/car rentals (4% flights) applies to high booking values, so absolute payouts are meaningful; brand-published rate card.", "contact_access": "Join route is via Impact from the brand page; no public partnerships email was verified.", "credibility": "Long-running global OTA; rate card verified on its own page.", "niche_fit": "Hotel and flight booking is core travel-creator inventory - destination guides, hotel reviews and itinerary content.", "opportunity_availability": "Open Impact program; standard network approval applies.", "ugc_evidence": "Open network program presented on the brand''s own page; no dedicated creator page was verified beyond it."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('TravlFi', 'https://travlfi.com/', 'Mobile internet service for RVers and travellers - portable hotspots and data plans for life on the road. Its own affiliate page pays 10% on all product sales with a 30-day cookie and a $242 average order, joining through ShareASale or Impact, and the brand separately runs an Ambassador Program aimed at RVers and creators.', null, 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'travel'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'ShareASale', 10, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by http://travlfi.com/pages/affiliate-program.', 'http://travlfi.com/pages/affiliate-program', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'TravlFi Affiliate Program (ShareASale / Impact)', 'http://travlfi.com/pages/affiliate-program', 'http://travlfi.com/pages/affiliate-program', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'http://travlfi.com/pages/affiliate-program', 'official_program_page', 'commission_rate', 'TravlFi''s own affiliate page states 10% commission on all product sales, sign-up via ShareASale or Impact, a 30-day cookie and a $242 average order value. No earnings-cap statement appears, so the cap is recorded as unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'http://travlfi.com/pages/affiliate-program', 'official_program_page', 'creator_program', 'The same page sits alongside a separate Ambassador Program explicitly recruiting RVers and travel creators - a defined creator route for the RV-life niche. No creator counts are published, so creator_saturation stays unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 22, 15, 14, 9, 9, 3, '{"compensation": "10% on all product sales against a $242 average order (about $24 per sale) is solid; brand-published.", "contact_access": "Apply on the brand''s own page into ShareASale or Impact; no public affiliate email was verified.", "credibility": "Niche travel-connectivity brand with complete published terms; smaller scale than the big OTAs.", "niche_fit": "RV and van-life connectivity is a tight, high-intent niche - road-life creators film their setup constantly.", "opportunity_availability": "Open application on the brand page via two networks.", "ugc_evidence": "A dedicated Ambassador Program for RVers and creators runs alongside the open affiliate program on the brand''s own page."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Welcome Pickups', 'https://www.welcomepickups.com/', 'Airport transfer and sightseeing-ride service with professional local drivers in 300+ destinations. Its creator-facing route is the Travelpayouts network offer: 8% on operated airport transfers and 9% on sightseeing rides with a 45-day cookie, paid once rides are actually operated; the brand''s separate Ambassador Program is a B2B partner-referral scheme for hotels and agents, not the creator route.', null, 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'travel'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Travelpayouts', 8, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://www.affiliates-directory.com/websites/welcome-pickups.', 'https://www.affiliates-directory.com/websites/welcome-pickups', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Welcome Pickups Affiliate Program (Travelpayouts)', 'https://www.affiliates-directory.com/websites/welcome-pickups', 'https://www.affiliates-directory.com/websites/welcome-pickups', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.affiliates-directory.com/websites/welcome-pickups', 'affiliate_network', 'commission_rate', 'The Travelpayouts offer profile for Welcome Pickups states an 8-9% percentage-of-sale model through Travelpayouts: 8% on operated airport transfers, 9% on sightseeing rides, with rewards tied to rides actually being operated, web bookings only (in-app not rewarded) and no coupon or media-buying promotion. The 8% core-transfer rate is recorded. No earnings-cap statement appears, so the cap is recorded as unknown.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://travuso.com/guides/best-travel-affiliate-programs', 'affiliate_directory', 'commission_rate', 'The travuso travel-program comparison (rates as listed in the Travelpayouts brands directory, November 2026) independently lists Welcome Pickups at 8-9% with a 45-day cookie, joined through Travelpayouts - two sources agree on rate, cookie and network.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 13, 12, 9, 8, 4, '{"compensation": "8% on transfers (9% sightseeing) with a 45-day cookie is competitive for ground transport; network-reported by two sources.", "contact_access": "Join route is via Travelpayouts through the offer profile; no public partnerships email was verified.", "credibility": "Established transfer service in 300+ destinations; terms rest on the network offer profile plus an independent comparison.", "niche_fit": "Airport-transfer booking is a natural add-on in destination and itinerary content - arrival-day logistics convert well.", "opportunity_availability": "Open Travelpayouts offer; standard network approval applies.", "ugc_evidence": "Travelpayouts is a creator-first travel network; the offer is documented for travel publishers, though the brand''s own ambassador scheme is B2B and excluded from this listing''s route."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Kiwi.com', 'https://www.kiwi.com/', 'Flight, train and bus booking platform known for ''virtual interlining'' - combining separate carriers into one itinerary. Through Travelpayouts it pays a flat 3% of the full booking price with a 30-day cookie; the offer''s stated average booking is $450 (about $13.50 per booking). The rate is low and the brand''s consumer reviews are mixed, which the score reflects.', null, 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'travel'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Travelpayouts', 3, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://www.travelpayouts.com/blog/high-paying-travel-affiliate-programs/.', 'https://www.affiliates-directory.com/websites/kiwi-com', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Kiwi.com Affiliate Program (Travelpayouts)', 'https://www.affiliates-directory.com/websites/kiwi-com', 'https://www.travelpayouts.com/blog/high-paying-travel-affiliate-programs/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.travelpayouts.com/blog/high-paying-travel-affiliate-programs/', 'affiliate_network', 'commission_rate', 'Travelpayouts'' own published offer table lists Kiwi.com at ''3% of the full booking price'' with a 30-day cookie lifetime and an average affiliate reward of €11.10. No earnings-cap statement appears, so the cap is recorded as unknown.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.affiliates-directory.com/websites/kiwi-com', 'affiliate_directory', 'commission_rate', 'The Kiwi.com offer profile restates the flat 3% commission calculated on the full price of any booking, an average booking value of $450 (about $13.50 average reward) and coverage of flight, train and bus tickets; Lasso and travuso independently agree on 3% with a 30-day cookie.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 12, 8, 9, 8, 3, '{"compensation": "3% is a low rate, partly offset by the $450 average booking (about $13.50 per booking); network-published with full clarity.", "contact_access": "Join route is via Travelpayouts through the offer profile; no public partnerships email was verified.", "credibility": "Large, well-known booking platform, but consumer reviews are mixed, which tempers the credibility score.", "niche_fit": "Cheap-flight hunting and unusual route combinations are proven travel-content formats with huge search demand.", "opportunity_availability": "Open Travelpayouts offer; some brand approvals are selective per the offer profile.", "ugc_evidence": "Offer runs through the creator-focused Travelpayouts network; no dedicated creator page was verified."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('XTERRA Fitness', 'https://www.xterrafitness.com/', 'Home fitness equipment brand selling treadmills, exercise bikes, ellipticals and rowers. Its own affiliate page offers 8% commission on referred sales with sign-up through Impact and monthly payouts, and publishes a phone contact (870-336-4286) on the page.', null, 'published') returning id into bid;
