  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 22, 12, 12, 9, 8, 4, '{"compensation": "8% on big-ticket equipment (treadmills run into four figures) means meaningful per-sale payouts; brand-published.", "contact_access": "Apply via the brand page into Impact; a phone number is published on the page, but no affiliate email was verified.", "credibility": "Established home-fitness equipment brand; rate and network verified on its own page.", "niche_fit": "Home-gym equipment reviews and setup tours are steady fitness-creator content, especially treadmills and rowers.", "opportunity_availability": "Open Impact program; standard network approval applies.", "ugc_evidence": "Open network program presented on the brand''s own page; no creator-specific program page was verified."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Hyperice', 'https://hyperice.com/', 'Recovery-technology brand - percussion massage guns, vibrating rollers and heat/compression wearables used by professional athletes. Its Awin merchant profile states only that affiliates ''earn up to 10%'', which is a ceiling rather than a base rate, so the rate is recorded as null rather than guessed; the profile names its agency contact at Wellblum.', null, 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'fitness'), true);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'partnerships', 'natasha@wellblum.com', null, 'https://ui.awin.com/merchant-profile/25763', 'needs_review', null);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Awin', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://ui.awin.com/merchant-profile/25763.', 'https://ui.awin.com/merchant-profile/25763', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Hyperice Affiliate Program (Awin)', 'https://ui.awin.com/merchant-profile/25763', 'https://ui.awin.com/merchant-profile/25763', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/25763', 'affiliate_network', 'affiliate_program', 'Hyperice''s Awin merchant profile (merchant ID 25763) confirms the brand runs an affiliate programme on Awin, but states only ''earn up to 10%'' - an ''up to'' figure is a rate ceiling, not a base rate, so commission_rate is recorded as null rather than guessed, and no earnings-cap statement appears, so the cap stays unknown. The profile names the programme''s agency contact as natasha@wellblum.com (Wellblum), which is the contact recorded.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 13, 7, 11, 8, 5, '{"compensation": "Only an ''up to 10%'' ceiling is published, so the rate is null and compensation scores low until confirmed inside Awin.", "contact_access": "A named agency contact email (natasha@wellblum.com) is published on the Awin profile - better than most network-only listings.", "credibility": "Category-leading recovery brand used across pro sports; programme existence verified on Awin itself.", "niche_fit": "Recovery routines are a core fitness-creator format - warm-up, post-workout and injury-prevention content.", "opportunity_availability": "Open Awin programme confirmed on the network profile.", "ugc_evidence": "Verified Awin programme from a brand heavily promoted by athletes and creators; no creator-specific program page was verified."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Pvolve', 'https://www.pvolve.com/', 'Low-impact functional fitness brand - streaming workouts plus proprietary sculpting equipment, fronted by high-profile creator partnerships. Its program runs on Impact; the directory listing states the payout as ''$15, 8% per sale'' - a $15 flat component plus 8% per sale - open to all regions. The 8% percentage is recorded, with the flat component documented in the evidence.', null, 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'fitness'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Impact', 8, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://linkclicky.com/affiliate-program/pvolve/.', 'https://linkclicky.com/affiliate-program/pvolve/', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Pvolve Affiliate Program (Impact)', 'https://linkclicky.com/affiliate-program/pvolve/', 'https://linkclicky.com/affiliate-program/pvolve/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkclicky.com/affiliate-program/pvolve/', 'affiliate_directory', 'commission_rate', 'The LinkClicky affiliate directory profile for Pvolve (dated March 11, 2024) lists the program on Impact, open to all regions, with commission stated as ''$15,8% per sale'', and its FAQ repeats: ''The commission rate for Pvolve is $15,8% per sale. This is just what''s officially listed with their affiliate program as the payout.'' The 8% per-sale rate is recorded and the $15 flat component is documented here. No earnings-cap statement appears, so the cap is recorded as unknown.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.influencerrate.com/affiliate-program/pvolve', 'affiliate_directory', 'commission_rate', 'InfluencerRate''s Pvolve program guide describes commissions of ''between 5% and 10%'' of sale value varying by product type (equipment vs membership), with a 30-day cookie - the recorded 8% sits inside that published range, consistent with a mixed flat-plus-percentage structure across product types.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 13, 13, 9, 8, 4, '{"compensation": "8% per sale plus a $15 flat component (per the directory''s official listing) is above standard for fitness programs; directory-reported, not brand-page-verified.", "contact_access": "Join route is via Impact through the directory profile; no public partnerships email was verified.", "credibility": "Well-known fitness brand with celebrity-backed visibility; terms rest on two directory sources that bracket the same rate.", "niche_fit": "Low-impact, joint-friendly training is a fast-growing women''s fitness niche with strong at-home content demand.", "opportunity_availability": "Open Impact program, all regions per the directory profile.", "ugc_evidence": "The brand markets heavily through creator partnerships and its program is open to publishers and influencers on Impact."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Fresh Clean Threads', 'https://freshcleantees.com/', 'Men''s basics brand (formerly Fresh Clean Tees) selling fitted tees, polos and essentials, largely by the pack. Its affiliate program runs on Impact at 8% per sale with a 30-day cookie, listed consistently across affiliate directories, and the brand also runs a creator program from its own program page.', null, 'published') returning id into bid;
