  insert into public.brands (name, website, description, country, status) values ('Epomaker', 'https://epomaker.com', 'Mechanical keyboard and desk-accessory brand selling hot-swappable keyboards, switches, keycaps and mice through epomaker.com. Its own Standard Affiliate page publishes a flat 5% commission on every referred sale, a 14-day cookie for custom links, monthly consolidated payouts, and states the program is managed through UpPromote.', 'China', 'published') returning id into bid;
