  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Epomaker Standard Affiliate Program — brand''s own page publishes 5% commission via UpPromote, 14-day cookie, monthly payouts', 'https://epomaker.com/pages/standard-affiliate', 'https://epomaker.com/pages/standard-affiliate', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://epomaker.com/pages/standard-affiliate', 'official_site', 'affiliate', 'EPOMAKER''s own Standard Affiliate page fetched in full: ''Earn 5% Commission for Referral Sales'', ''5% Commission on Each Referred Sale'', ''14-Day Cookies for Custom Links'', commissions consolidated and paid around the 10th of each month, free to join with no application fee or minimum sales quota, and ''We''ve partnered with UpPromote to manage our Affiliate program''. A separate higher-tier creator route exists (the brand''s .kr storefront lists 5-10% tiers for creators), but the recorded 5% is the brand-published standard rate on the global store. Epomaker''s own contact and creator pages list affiliate contact emails in search indexes, but those pages returned 404 when fetched, so no email is recorded here. No earnings-cap statement is published, so the cap is unknown, and no creator count is published, so saturation stays unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 15, 10, 8, 9, 4, '{"compensation": "A flat brand-published 5% is modest for hardware, though keyboards are mid-ticket and the brand runs higher creator tiers elsewhere; no cap statement is published", "contact_access": "Application runs from the brand''s own program page into UpPromote; no affiliate email could be verified on a fetched page", "credibility": "An established global keyboard brand with a large community following and its own storefront", "niche_fit": "Mechanical keyboards are core desk-setup and tech UGC \u2014 sound tests, switch swaps, unboxings and desk tours are natural creator content", "opportunity_availability": "Open application, free to join, no minimum sales quota; acceptance confirmed by email", "ugc_evidence": "A brand-published program explicitly recruiting community members to share products on social media, blogs and email, plus a separate creator tier on the brand''s regional storefront"}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Fulgenix Pets', 'https://www.fulgenix.com', 'Pet digestive-health brand selling a single flagship supplement (Fulgenix Digestive Tract Protector, a Health Canada-registered Veterinary Health Product) through fulgenix.com. Its own Partner Program page — aimed at pet influencers, bloggers and professionals — publishes 50% commission on a customer''s first month''s purchase and a 30-day attribution duration, with automated payouts.', 'Canada', 'published') returning id into bid;
