  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Fulgenix Partner Program — brand''s own page publishes 50% commission on the first month''s purchase (basis: first month only), 30-day duration, aimed at pet influencers and bloggers', 'https://www.fulgenix.com/pages/ambassador', 'https://www.fulgenix.com/pages/ambassador', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.fulgenix.com/pages/ambassador', 'official_site', 'affiliate', 'Fulgenix''s own Partner Program page fetched in full: ''50% COMMISSION — Earn 50% commission on first month''s purchase, regardless of order type or size'', ''30 DAY DURATION — Earn commissions when users purchase through your unique link within 30 days'', and ''AUTOMATED PAYOUTS''. The page recruits ''Pet influencers'', ''Pet bloggers'', ''Social media stars'', pet professionals and affiliate marketers, and requires a website, blog or social presence in pet health topics. BASIS NOTE: the 50% applies to the first month''s purchase only, and it is recorded on that basis. No tracking platform is named on the page, so the route is recorded as brand direct. No earnings-cap statement is published, so the cap is unknown, and no creator count is published, so saturation stays unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 15, 18, 9, 8, 3, '{"compensation": "50% is the highest rate in this round, though it applies only to the first month''s purchase of a single-product catalogue, which limits lifetime value per referral", "contact_access": "Application is through the brand''s own partner page; no affiliate email is published", "credibility": "A small single-product brand; the product is a Health Canada-registered Veterinary Health Product, but the company is far less established than the global brands in this round", "niche_fit": "Pet digestive health is a focused supplement niche \u2014 gut-health stories, senior-dog care and before/after content fit pet UGC well", "opportunity_availability": "Open application on the brand''s own page for influencers, bloggers and pet professionals, subject to fit review", "ugc_evidence": "The brand''s own page is built specifically around influencers, bloggers and social media creators rather than generic affiliates"}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Freewell', 'https://freewellgear.com', 'Camera-gear brand with 10+ years in the industry, selling premium lenses, ND and magnetic filters and accessories for photographers and filmmakers through freewellgear.com. Its affiliate program runs on UpPromote with a manually vetted creator registration form; a platform case study documents $350,000 of affiliate revenue in two months and a global network of around 700 creators — but no commission percentage is published, so the rate is honestly null.', 'India', 'published') returning id into bid;
