  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Freewell Affiliate Program — UpPromote-run creator program documented in a platform case study (~700 creators, $350K affiliate revenue in two months); commission rate unpublished, recorded as null', 'https://freewellgear.com', 'https://uppromote.com/case-study/freewell-gear/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://uppromote.com/case-study/freewell-gear/', 'directory', 'affiliate', 'UpPromote''s own case study of Freewell Gear, fetched in full: the brand migrated to Shopify in January 2025, ''chose UpPromote'' to run its affiliate program, recruits through a registration form with repeated manual review, prioritizes technically skilled creators over follower counts, sends free samples to trusted creators, and reports ''a global network of around 700 creators'' and ''$350,000 in affiliate revenue in just two months'' (270 referrals in September 2025). SATURATION NOTE: ~700 creators globally is a mid-size program, so saturation is recorded as unknown, NOT low. The case study publishes no commission percentage, and no brand page publishing one could be fetched, so the rate is honestly null. No earnings-cap statement is published, so the cap is unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 16, 8, 8, 8, 4, '{"compensation": "No commission percentage is published anywhere fetchable, so compensation can only be scored on the program''s documented revenue results, not its rate", "contact_access": "Recruitment is through the brand''s own registration form on its store; no affiliate email is published", "credibility": "A 10+ year camera-gear brand with a documented, revenue-producing affiliate program", "niche_fit": "Filters and lenses for mirrorless and action cameras are pure filmmaker/photographer UGC \u2014 tests, comparisons and field footage", "opportunity_availability": "Open registration form, but every applicant is manually vetted several times for technical skill", "ugc_evidence": "The case study documents a creator-first program: manual vetting for expertise, free samples, no scripted messaging, and ~700 active creators"}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Finn', 'https://www.petfinn.com', 'Dog wellness brand selling vet-formulated supplement chews and grooming products (calming, hip and joint, skin and coat, probiotics) through petfinn.com. Its affiliate program is reported at 7% per sale with a 15-day cookie by Lasso, but a second directory reports a 5-10% range — the figures conflict, so the rate is honestly null with the conflict documented, and the tracking network is not publicly named.', 'United States', 'published') returning id into bid;
