  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/finn/', 'directory', 'affiliate', 'Lasso''s Finn program profile, fetched in full, reports ''Commission Rate: 7% Per Sale'' and ''Cookie Duration: 15 Days'', aimed at pet bloggers, with approval typically within a few days. CONFLICT: Shopper''s partnership listing for Finn reports a 5%-10% commission range for the same program. Because the two published figures conflict and no brand page settles them, the commission rate is recorded as null with this conflict documented. Neither source names the tracking network, so the network is honestly recorded as unknown. No earnings-cap statement is published, so the cap is unknown, and no creator count is published, so saturation stays unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 12, 8, 7, 8, 4, '{"compensation": "Published rates conflict (7% flat vs a 5-10% range) and no brand page settles them, so the rate is null and compensation scores low until verified", "contact_access": "Application runs through the brand''s site via directory reporting; no affiliate email is published and the tracking network is not named", "credibility": "An established US dog-wellness brand with vet-formulated products and national retail presence", "niche_fit": "Dog supplement chews are staple pet UGC \u2014 daily-routine, anxiety and joint-care content for dog creators", "opportunity_availability": "Open application reported, with approval typically within a few days", "ugc_evidence": "Directory reporting describes a program aimed at pet bloggers and enthusiasts; no dedicated creator tier was verified on a brand page"}'::jsonb);
